const sspDomains=[['tactile','Sensitiviti sentuhan','Tactile Sensitivity'],['tasteSmell','Sensitiviti rasa / bau','Taste/Smell Sensitivity'],['movement','Sensitiviti pergerakan','Movement Sensitivity'],['underresponsive','Kurang respons / mencari sensasi','Underresponsive/Seeks Sensation'],['auditoryFiltering','Penapisan auditori','Auditory Filtering'],['lowEnergy','Tenaga rendah / lemah','Low Energy/Weak'],['visualAuditory','Sensitiviti visual / auditori','Visual/Auditory Sensitivity']];
const sspSections=[['problem','Sebab penilaian','Reason for assessment','Kebimbangan penjaga dan tujuan merekod Short Sensory Profile.'],...sspDomains.map(([key,label,en])=>[key,label,en,'Ringkasan dapatan daripada soal selidik penjaga dan kesannya pada aktiviti harian. Jika tidak dapat dinilai, nyatakan sebab.']),['impression','Rumusan Occupational Therapist','OT interpretation','Gabungkan laporan penjaga, pemerhatian dan konteks aktiviti. Rekod ini tidak menetapkan diagnosis.'],['recommendations','Cadangan & susulan','Recommendations','Keutamaan intervensi, panduan penjaga dan pelan penilaian atau susulan.']];
const isSspAssessment=a=>a?.type==='ot-ssp';
function sspWithinAge(dob,date){if(!dob||!date)return false;const birth=new Date(dob+'T00:00:00Z'),at=new Date(date+'T00:00:00Z');if(!Number.isFinite(+birth)||!Number.isFinite(+at))return false;const min=new Date(birth),max=new Date(birth);min.setUTCFullYear(min.getUTCFullYear()+3);max.setUTCFullYear(max.getUTCFullYear()+11);return at>=min&&at<max}
function sspAgeNotice(a){if(!a.dob||!a.respondentDate)return 'SSP asal: umur 3:0–10:11. Isi tarikh lahir dan tarikh soal selidik penjaga.';return sspWithinAge(a.dob,a.respondentDate)?'Umur pada tarikh soal selidik dalam julat SSP asal (3:0–10:11).':'Umur pada tarikh soal selidik di luar julat SSP asal (3:0–10:11). Simpan draf dan semak instrumen yang sesuai.'}
function sspAdditionalFields(a){return `<fieldset><legend>02 · Soal selidik penjaga</legend><p class="field-hint">Short Sensory Profile asal (SSP, 1999) · 38 item · Rekod pendamping. Gunakan borang dan manual rasmi. Templat ini bukan Short Sensory Profile 2.</p><p id="ssp-age-notice" role="status">${esc(sspAgeNotice(a))}</p><div class="assessment-fields">${assessmentInput('respondentName','Nama penjaga / responden',a.respondentName)}${assessmentInput('respondentRelationship','Hubungan dengan murid',a.respondentRelationship)}${assessmentInput('respondentDate','Tarikh soal selidik penjaga',a.respondentDate,'date')}${assessmentInput('instrumentReference','Bahasa / versi borang SSP asal dan manual',a.instrumentReference)}${assessmentInput('formReference','Rujukan borang rasmi yang dilengkapkan',a.formReference)}${assessmentInput('responseContext','Konteks pemerhatian penjaga (pilihan)',a.responseContext)}</div><p class="field-hint">Tarikh assessment ialah tarikh semakan OT. Julat umur SSP disemak pada tarikh soal selidik penjaga.</p></fieldset>`}
function sspScoreInput(key,label,value){return `<label class="field">${label}<input name="${key}" type="number" min="0" step="1" inputmode="numeric" value="${esc(value??'')}" placeholder="Belum direkod"></label>`}
function sspDomainFields(a,key){return `<div class="assessment-fields">${sspScoreInput(key+'Score','Skor mentah daripada borang rasmi (pilihan)',a[key+'Score'])}${assessmentInput(key+'Classification','Klasifikasi rasmi / sebab tiada skor (pilihan)',a[key+'Classification'])}</div>`}
function sspResultFields(a){return `<fieldset><legend>13 · Ringkasan skor & semakan</legend><p class="field-hint">Salin skor dan klasifikasi selepas menyemak manual. Ruang kosong bermakna belum direkod, bukan sifar. Tiada jumlah atau klasifikasi dikira oleh sistem.</p><div class="assessment-fields">${sspScoreInput('sspTotal','Skor keseluruhan rasmi (pilihan)',a.sspTotal)}${assessmentInput('sspOverall','Rumusan klasifikasi rasmi / sebab tidak dapat diskor',a.sspOverall)}${assessmentInput('followUpDate','Tarikh susulan (pilihan)',a.followUpDate,'date')}</div><label class="assessment-confirm"><input type="checkbox" name="officialReviewed" ${a.officialReviewed?'checked':''}> Saya telah menyemak borang SSP asal yang dilengkapkan penjaga, ketepatan pemindahan skor dan tafsiran mengikut manual rasmi.</label><p class="field-hint"><a href="https://www.pearsonassessments.com/en-us/Store/Professional-Assessments/Behavior/Sensory-Profile-/p/100000566" target="_blank" rel="noopener noreferrer">Rujukan Short Sensory Profile asal — Pearson</a></p></fieldset>`}
function validateSsp(a,complete){const validDate=v=>/^\d{4}-\d{2}-\d{2}$/.test(v||'')&&Number.isFinite(Date.parse(v))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v;for(const key of [...sspDomains.map(([key])=>key+'Score'),'sspTotal']){const value=a[key];if(value!==undefined&&value!==null&&value!==''&&(!/^\d+$/.test(String(value))||!Number.isSafeInteger(Number(value))))return 'Skor SSP mesti nombor bulat tidak negatif, atau dibiarkan kosong.'}if(a.respondentDate&&!validDate(a.respondentDate))return 'Sila isi tarikh soal selidik yang sah.';if(a.respondentDate&&a.respondentDate>a.date)return 'Tarikh soal selidik penjaga tidak boleh selepas tarikh assessment.';if(a.dob&&a.respondentDate&&a.respondentDate<a.dob)return 'Tarikh soal selidik tidak boleh sebelum tarikh lahir.';if(a.followUpDate&&(!validDate(a.followUpDate)||a.followUpDate<a.date))return 'Tarikh susulan mesti sah dan tidak boleh sebelum tarikh assessment.';if(!complete)return '';for(const [key,label] of [['respondentName','nama penjaga / responden'],['respondentRelationship','hubungan penjaga'],['respondentDate','tarikh soal selidik penjaga'],['instrumentReference','bahasa / versi borang SSP asal'],['formReference','rujukan borang rasmi'],['sspOverall','rumusan klasifikasi atau sebab tidak dapat diskor']])if(!a[key]?.trim())return `Sila isi ${label}.`;if(!sspWithinAge(a.dob,a.respondentDate))return 'Umur di luar julat SSP asal 3:0–10:11 pada tarikh soal selidik. Simpan sebagai draf.';if(!a.officialReviewed)return 'Sila sahkan semakan borang dan manual SSP asal.';return ''}
function sspReportMetadata(a){return `<section><h4>Short Sensory Profile asal · SSP 1999</h4><p>Rekod pendamping soal selidik penjaga. Skor dan klasifikasi dimasukkan oleh terapis daripada borang rasmi; bukan pemarkahan automatik.</p><dl>${[['Responden',a.respondentName],['Hubungan',a.respondentRelationship],['Tarikh soal selidik',a.respondentDate],['Umur pada soal selidik',assessmentAge(a.dob,a.respondentDate)],['Bahasa / versi borang',a.instrumentReference],['Rujukan borang',a.formReference],['Konteks',a.responseContext],['Skor keseluruhan',a.sspTotal],['Rumusan klasifikasi',a.sspOverall],['Tarikh susulan',a.followUpDate]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v===0?'0':v||'Belum direkod')}</dd></div>`).join('')}</dl></section>`}
function sspReportDomain(a,key){return `<p>Skor mentah: ${esc(a[key+'Score']===0?'0':a[key+'Score']||'Belum direkod')}<br>Klasifikasi / catatan: ${esc(a[key+'Classification']||'Belum direkod')}</p>`}
